package com.atakmap.android.aleph.download;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import java.io.File;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;

/**
 * Against a package the Python service really wrote (src/test/resources, regenerated by
 * service/tests/make_atak_fixture.py): one DTED1 cell w090/n39 with a 10×10 block of 200 m
 * posts at profiles 100–109, posts 200–209, one post at -12 m, voids elsewhere.
 */
public class DtedInstallerTest {

    @Rule
    public TemporaryFolder tmp = new TemporaryFolder();

    private File pkg;
    private File dtedRoot;

    @Before
    public void setUp() throws Exception {
        pkg = tmp.newFile("package.zip");
        try (InputStream in = getClass().getClassLoader().getResourceAsStream("aleph-package-dted1.zip")) {
            Files.copy(in, pkg.toPath(), StandardCopyOption.REPLACE_EXISTING);
        }
        dtedRoot = tmp.newFolder("DTED");
    }

    @Test
    public void newCellIsCopiedAndReadsBackExactly() throws Exception {
        DtedInstaller.Result result = DtedInstaller.install(pkg, dtedRoot);
        assertEquals(1, result.added);
        DtedCell cell = DtedCell.read(new File(dtedRoot, "w090/n39.dt1"));
        assertEquals(200, cell.height(100, 200));
        assertEquals(-12, cell.height(105, 205));   // signed magnitude decoded
        assertEquals(DtedCell.VOID, cell.height(0, 0));
    }

    @Test
    public void pathTraversalEntriesAreNeverWritten() throws Exception {
        DtedInstaller.install(pkg, dtedRoot);
        assertFalse(new File(dtedRoot.getParentFile(), "evil.dt1").exists());
        assertFalse(new File(dtedRoot, "evil.dt1").exists());
    }

    @Test
    public void existingHeightsAreNeverOverwrittenOnlyVoidsFilled() throws Exception {
        DtedInstaller.install(pkg, dtedRoot);
        File cellFile = new File(dtedRoot, "w090/n39.dt1");

        // A device that already had this cell: real data at (0,0) and at one post Aleph also
        // has, and a void where Aleph has 200 m.
        DtedCell existing = DtedCell.read(cellFile);
        existing.set(0, 0, 321);
        existing.set(100, 200, 199);
        existing.set(101, 201, DtedCell.VOID);
        existing.write(cellFile);

        DtedInstaller.Result result = DtedInstaller.install(pkg, dtedRoot);
        assertEquals(1, result.merged);
        DtedCell merged = DtedCell.read(cellFile);
        assertEquals(321, merged.height(0, 0));     // device data outside the capture kept
        assertEquals(199, merged.height(100, 200)); // device data inside the capture kept
        assertEquals(200, merged.height(101, 201)); // device void filled from the capture
    }

    @Test
    public void identicalCellIsLeftUntouched() throws Exception {
        DtedInstaller.install(pkg, dtedRoot);
        File cellFile = new File(dtedRoot, "w090/n39.dt1");
        long before = cellFile.lastModified();
        DtedInstaller.Result result = DtedInstaller.install(pkg, dtedRoot);
        assertEquals(0, result.added + result.merged);
        assertEquals(before, cellFile.lastModified());
        assertTrue(cellFile.isFile());
    }

    @Test
    public void rewrittenCellKeepsValidChecksums() throws Exception {
        DtedInstaller.install(pkg, dtedRoot);
        File cellFile = new File(dtedRoot, "w090/n39.dt1");
        DtedCell cell = DtedCell.read(cellFile);
        cell.set(5, 5, -400);
        cell.write(cellFile);
        assertEquals(-400, DtedCell.read(cellFile).height(5, 5));  // read() re-validates sentinels
    }
}
